#!/usr/bin/env python3
"""Checks for patch_notes.py: reading a PR body, the game-change test, and the two entries."""
import os
import sys
import unittest

sys.path.insert(0, os.path.dirname(__file__))
import patch_notes as pn  # noqa: E402

BODY = """<!-- claude-projects-attribution: {"github_login":"x"} -->
_Requested by **Cain** · [project thread](https://claude.ai/code/project/x)_

## What
Dev words about `some_function` in file.rs.

## Patch note
**TLDR:** You can now call a recruit. Try it on a top target.
- A call counts as half a sit-down. (PR #1)
- His family calls you back.
Look at: open a recruit's file and press Call.
Title: Call and text recruits

---
_Generated by [Claude Code](https://claude.ai/code/session_x)_
"""


class T(unittest.TestCase):
    def test_section(self):
        i = pn.parse_body("Lane 4: calls", BODY)
        self.assertFalse(i["auto"])
        self.assertEqual(i["title"], "Call and text recruits")
        self.assertEqual(i["tldr"], "You can now call a recruit. Try it on a top target.")
        self.assertEqual(len(i["bullets"]), 2)
        self.assertEqual(i["look"], "open a recruit's file and press Call.")
        self.assertTrue(i["players"])

    def test_players_no(self):
        i = pn.parse_body("t", "## Patch note\nPlayers: no\n")
        self.assertFalse(i["players"])
        self.assertFalse(i["auto"])

    def test_fallback(self):
        i = pn.parse_body("Fix thing", "_Requested by **Cain** · x\n\n## What\nHovering a skill now explains it. More words.\n- plain line\n- uses `code_here`\n")
        self.assertTrue(i["auto"])
        self.assertEqual(i["tldr"], "Hovering a skill now explains it.")
        self.assertEqual(i["bullets"], ["plain line"])

    def test_pr_number(self):
        self.assertEqual(pn.pr_number("Merge pull request #428 from a/b"), 428)
        self.assertEqual(pn.pr_number("Team page: x (#398)"), 398)
        self.assertIsNone(pn.pr_number("Merge main into the stale follow-up"))

    def test_game_files(self):
        pats = pn.ignore_patterns()
        self.assertFalse(pn.is_game_file("docs/design/x.md", pats))
        self.assertFalse(pn.is_game_file("CLAUDE.md", pats))
        self.assertFalse(pn.is_game_file(".github/workflows/x.yml", pats))
        self.assertTrue(pn.is_game_file("crates/afm-game/src/lib.rs", pats))
        self.assertTrue(pn.is_game_file("app/ui/pregame.js", pats))

    def test_entries(self):
        info = pn.parse_body("Lane 4: calls", BODY)
        item = {"sha": "x", "subject": "s", "pr": 5, "game": True, "info": info}
        e = {"n": 500, "sha": "x", "date": "1 Jan", "items": [item]}
        team = pn.render_team(e)
        self.assertIn("## 0.2.500 (1 Jan, shipped): call and text recruits (PR #5)", team)
        self.assertIn("**TLDR:** You can now call a recruit.", team)
        game = pn.player_entry(e)
        self.assertEqual(game["v"], "0.2.500")
        self.assertNotIn("PR #", " ".join(game["notes"]))
        quiet = {"n": 501, "sha": "x", "date": "2 Jan", "items": [{**item, "game": False}]}
        self.assertIn("no game change", pn.render_team(quiet))
        self.assertIsNone(pn.player_entry(quiet))
        auto = {**item, "info": {**info, "auto": True}}
        self.assertIsNone(pn.player_entry({**e, "items": [auto]}))
        no = {**item, "info": {**info, "players": False}}
        self.assertIsNone(pn.player_entry({**e, "items": [no]}))


if __name__ == "__main__":
    unittest.main()
